+	u32 output_size;
+	dma_addr_t cmdbufs_iova;
+	u32 cmdbufs_size;
+	void *priv;
+};
+
+struct icp_hfi *icp_hfi_get(struct device *dev);
+void icp_hfi_put(struct icp_hfi *hfi);
+
+#endif /* __CAMSS_ICP_H__ */

